75	pub fn coverage(spec: &DepSpec, new: &Version) -> Result<Coverage, GrammarMismatch> {
76	    match spec {
77	        DepSpec::Exact(v) => {
78	            if v == new {
79	                Ok(Coverage::Covers)
80	            } else {
81	                Ok(Coverage::DoesNotCover)
82	            }
83	        }
84	        DepSpec::CargoBare(v) => {
85	            if caret_covers(v, new)? {
86	                Ok(Coverage::Covers)
87	            } else {
88	                Ok(Coverage::DoesNotCover)
89	            }
90	        }
91	        DepSpec::Range(req, _) => {
92	            if req.matches(new)? {
93	                Ok(Coverage::Covers)
94	            } else {
95	                Ok(Coverage::DoesNotCover)
96	            }
97	        }
98	        DepSpec::Workspace(_) => Ok(Coverage::Covers),
99	        DepSpec::WorkspaceProtocol(workspace) => workspace.coverage(new),
100	        DepSpec::Catalog(_) | DepSpec::Opaque(_) => Ok(Coverage::Unknown),
101	    }
102	}
