184	/// Propagates `input.seed`'s severities outward to dependents until no
185	/// target version changes, or `convergence_bound`'s iteration cap is
186	/// exceeded ([`GraphError::CascadeNotConverged`]) -- turns a would-be
187	/// infinite loop into a reportable bug, bound derived from package count.
188	///
189	/// One pass: pop a package, compute its bumped target, walk every
190	/// dependent edge, apply [`cascade_action`] to decide if that dependent's
191	/// severity/target changes and gets re-queued.
192	///
193	/// A genuine cross-grammar coverage failure (`coverage`'s `Err`, e.g.
194	/// SemVer target vs. PEP440 spec) aborts the whole cascade with
195	/// `Err(GraphError::GrammarMismatch)`. Soft instead: `Catalog`/`Opaque`
196	/// specs never have coverage tested (`coverage` returns `Unknown`
197	/// unconditionally), so they can't block anything -- `Catalog` gets
198	/// [`DiagnosticCode::CatalogSpecNotRewritten`], `Opaque` gets no
199	/// diagnostic. [`DiagnosticCode::RangeNotRoundTrippable`]'s real trigger
200	/// is a different step: [`rewrite_spec`], when a mechanical range rewrite
201	/// (not a coverage test) fails on an otherwise-known-coverage spec.
202	pub fn solve_cascade<D: DependencyResolver>(input: CascadeInput<'_, D>) -> Result<CascadeOutcome, GraphError> {
203	    let mut out = CascadeOutcome {
204	        severities: input.seed.clone(),
205	        reasons: input.reasons.clone(),
206	        ..Default::default()
207	    };
208	
209	    for (id, &sev) in input.seed {
210	        let t = bump_target(id, sev, &input)?;
211	        out.targets.insert(id.clone(), t);
212	    }
213	
214	    let mut worklist: BTreeSet<PackageId> = out.targets.keys().cloned().collect();
215	    let mut iterations = 0;
216	    let bound = convergence_bound(input.graph.packages().count());
217	    // Edges already run through rewrite_spec, so the floor-raise pass below doesn't re-diagnose them.
218	    let mut rewrite_attempted: BTreeSet<RewriteKey> = BTreeSet::new();
219	
220	    let mut changed = true;
221	    while changed {
222	        changed = false;
223	
224	        while let Some(pkg) = worklist.pop_first() {
225	            iterations += 1;
226	            if iterations > bound {
227	                return Err(GraphError::CascadeNotConverged { iterations });
228	            }
229	
230	            let new_version = out.targets[&pkg].clone();
231	            let src_sev = out.severities[&pkg];
232	
233	            let dependents: Vec<DepEdge> = input.graph.dependents_of(&pkg).cloned().collect();
234	            for edge in dependents {
235	                let cov = coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
236	                    from: edge.from.clone(),
237	                    to: edge.to.clone(),
238	                    source,
239	                })?;
240	
241	                let d = cascade_action(edge.kind, cov, src_sev, input.cfg);
242	
243	                if d.unknown_coverage && !matches!(edge.spec, DepSpec::Opaque(_)) {
244	                    let code = match edge.spec {
245	                        DepSpec::Catalog(_) => DiagnosticCode::CatalogSpecNotRewritten,
246	                        _ => DiagnosticCode::RangeNotRoundTrippable,
247	                    };
248	                    out.diagnostics.push(Diagnostic {
249	                        code,
250	                        severity: DiagnosticSeverity::Warning,
251	                        message: format!(
252	                            "spec `{}` for `{}` could not be tested for coverage",
253	                            edge.spec.render(),
254	                            edge.to.display_name()
255	                        ),
256	                        package: Some(edge.from.clone()),
257	                        path: Some(edge.from_manifest.clone()),
258	                        governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
259	                        escalated_by: None,
260	                    });
261	                }
262	
263	                if d.rewrite {
264	                    match rewrite_edge(&edge, &new_version, input.cfg)? {
265	                        RewriteOutcome::Rewritten(to_spec) => {
266	                            let key = dependency_rewrite_key(&edge);
267	                            rewrite_attempted.insert(key.clone());
268	                            out.rewrites.insert(
269	                                key.clone(),
270	                                SpecRewrite {
271	                                    key,
272	                                    dependency: edge.to.clone(),
273	                                    from: edge.spec.clone(),
274	                                    to: to_spec,
275	                                },
276	                            );
277	                        }
278	                        RewriteOutcome::LeftAlone(dg) => {
279	                            rewrite_attempted.insert(dependency_rewrite_key(&edge));
280	                            out.diagnostics.push(dg);
281	                        }
282	                    }
283	                }
284	
285	                let cur_sev = out.severities.get(&edge.from).copied().unwrap_or(Severity::None);
286	                if d.severity > cur_sev {
287	                    raise(
288	                        &edge.from,
289	                        d.severity,
290	                        &d,
291	                        &pkg,
292	                        &edge,
293	                        &new_version,
294	                        &mut out,
295	                        input.groups,
296	                        &mut worklist,
297	                        &input,
298	                    )?;
299	                }
300	            }
301	        }
302	
303	        // Linked group release severity propagation
304	        for g in input.groups.linked.values() {
305	            let max_sev = g.max_severity(&out.severities);
306	            if max_sev == Severity::None {
307	                continue;
308	            }
309	
310	            // Skip members absent from `input.base`: `bump_target` would hit `MissingField`.
311	            let mut live_members = Vec::new();
312	            for id in g.package_members() {
313	                if !input.base.contains_key(id) {
314	                    out.diagnostics.push(Diagnostic {
315	                        code: DiagnosticCode::UnknownPackage,
316	                        severity: DiagnosticSeverity::Warning,
317	                        message: format!(
318	                            "Linked group `{}` references package `{}` which is not in the \
319	                             workspace; the stale group member is skipped. Remove it from \
320	                             callisto.toml to silence this warning.",
321	                            g.name,
322	                            id.display_name()
323	                        ),
324	                        package: Some(id.clone()),
325	                        path: None,
326	                        governed_by: Some(ConfigKey::LINKED_GROUP),
327	                        escalated_by: None,
328	                    });
329	                    continue;
330	                }
331	                live_members.push(id.clone());
332	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
333	                if max_sev > cur_sev {
334	                    out.severities.insert(id.clone(), max_sev);
335	                }
336	            }
337	
338	            let mut winner: Option<Version> = None;
339	            for id in &live_members {
340	                let candidate = bump_target(id, max_sev, &input)?;
341	                winner = Some(match winner {
342	                    None => candidate,
343	                    Some(best) => {
344	                        let cmp = Version::compare(&candidate, &best).map_err(|_grammar_mismatch| {
345	                            GraphError::GroupGrammarMismatch {
346	                                group: g.name.clone(),
347	                                members: live_members
348	                                    .iter()
349	                                    .filter_map(|m| out.targets.get(m).map(|v| (m.clone(), v.clone())))
350	                                    .collect(),
351	                            }
352	                        })?;
353	                        if cmp.is_gt() {
354	                            candidate
355	                        } else {
356	                            best
357	                        }
358	                    }
359	                });
360	            }
361	            let Some(winner) = winner else { continue };
362	
363	            for id in live_members {
364	                if out.targets.get(&id) != Some(&winner) {
365	                    out.targets.insert(id.clone(), winner.clone());
366	                    out.reasons
367	                        .insert(id.clone(), BumpReason::LinkedGroupUnion { group: g.name.clone() });
368	                    worklist.insert(id.clone());
369	                    changed = true;
370	                }
371	            }
372	        }
373	
374	        // Fixed groups converge on `fixed_group_target`, not the max of per-member candidates.
375	        for g in input.groups.fixed.values() {
376	            let max_sev = g.max_severity(&out.severities);
377	            if max_sev == Severity::None {
378	                continue;
379	            }
380	
381	            // Skip members absent from `input.base`: they would reach `out.severities` and panic in `plan_version`.
382	            let mut live_members = Vec::new();
383	            for id in g.package_members() {
384	                if !input.base.contains_key(id) {
385	                    out.diagnostics.push(Diagnostic {
386	                        code: DiagnosticCode::UnknownPackage,
387	                        severity: DiagnosticSeverity::Warning,
388	                        message: format!(
389	                            "Fixed group `{}` references package `{}` which is not in the \
390	                             workspace; the stale group member is skipped. Remove it from \
391	                             callisto.toml to silence this warning.",
392	                            g.name,
393	                            id.display_name()
394	                        ),
395	                        package: Some(id.clone()),
396	                        path: None,
397	                        governed_by: Some(ConfigKey::FIXED_GROUP),
398	                        escalated_by: None,
399	                    });
400	                    continue;
401	                }
402	                live_members.push(id.clone());
403	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
404	                if max_sev > cur_sev {
405	                    out.severities.insert(id.clone(), max_sev);
406	                }
407	            }
408	
409	            let winner =
410	                crate::groups::fixed_group_target(&g.name, &live_members, input.base, max_sev, input.tags, input.pre)?;
411	
412	            for id in live_members {
413	                if out.targets.get(&id) != Some(&winner) {
414	                    out.targets.insert(id.clone(), winner.clone());
415	                    out.reasons
416	                        .insert(id.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
417	                    worklist.insert(id.clone());
418	                    changed = true;
419	                }
420	            }
421	        }
422	    }
423	
424	    // A releasing package's floor on a co-released dependency is always raised, even when the old spec still covers it.
425	    for pkg in out.severities.keys().cloned().collect::<Vec<_>>() {
426	        let deps: Vec<DepEdge> = input.graph.dependencies_of(&pkg).cloned().collect();
427	        for edge in deps {
428	            if edge.kind == DepKind::Dev {
429	                continue;
430	            }
431	            if matches!(
432	                edge.spec,
433	                DepSpec::Workspace(_) | DepSpec::Catalog(_) | DepSpec::Opaque(_)
434	            ) {
435	                continue;
436	            }
437	            let Some(new_version) = out.targets.get(&edge.to).cloned() else {
438	                continue;
439	            };
440	            if matches!(edge.spec, DepSpec::WorkspaceProtocol(_))
441	                && coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
442	                    from: edge.from.clone(),
443	                    to: edge.to.clone(),
444	                    source,
445	                })? != Coverage::DoesNotCover
446	            {
447	                continue;
448	            }
449	
450	            let key = dependency_rewrite_key(&edge);
451	            if rewrite_attempted.contains(&key) {
452	                continue;
453	            }
454	
455	            // A floor that cannot be raised (`*`, a bare Python requirement, `||` sets) is harmless while it covers.
456	            if matches!(coverage(&edge.spec, &new_version), Ok(Coverage::Covers))
457	                && matches!(
458	                    rewrite_spec(
459	                        &edge.spec,
460	                        &new_version,
461	                        manifest_ecosystem(&edge.from_manifest),
462	                        input.cfg
463	                    ),
464	                    RewriteOutcome::LeftAlone(_)
465	                )
466	            {
467	                continue;
468	            }
469	
470	            match rewrite_edge(&edge, &new_version, input.cfg)? {
471	                RewriteOutcome::Rewritten(to_spec) => {
472	                    out.rewrites.entry(key.clone()).or_insert_with(|| SpecRewrite {
473	                        key,
474	                        dependency: edge.to.clone(),
475	                        from: edge.spec.clone(),
476	                        to: to_spec,
477	                    });
478	                }
479	                RewriteOutcome::LeftAlone(dg) => {
480	                    out.diagnostics.push(dg);
481	                }
482	            }
483	        }
484	    }
485	
486	    Ok(out)
487	}
