506	fn raise<D: DependencyResolver>(
507	    pkg: &PackageId,
508	    sev: Severity,
509	    decision: &CascadeDecision,
510	    via: &PackageId,
511	    edge: &DepEdge,
512	    dependency_to: &Version,
513	    out: &mut CascadeOutcome,
514	    groups: &GroupTable,
515	    worklist: &mut BTreeSet<PackageId>,
516	    input: &CascadeInput<'_, D>,
517	) -> Result<bool, GraphError> {
518	    let cur_sev = out.severities.get(pkg).copied().unwrap_or(Severity::None);
519	    if sev <= cur_sev {
520	        return Ok(false);
521	    }
522	
523	    out.severities.insert(pkg.clone(), sev);
524	
525	    let new_reason = if decision.escalated {
526	        BumpReason::PeerEscalation {
527	            via: via.clone(),
528	            spec: edge.spec.render(),
529	        }
530	    } else {
531	        BumpReason::Cascade {
532	            via: via.clone(),
533	            dep_kind: edge.kind,
534	            spec: edge.spec.render(),
535	            dependency_to: dependency_to.clone(),
536	        }
537	    };
538	    out.reasons.insert(pkg.clone(), new_reason);
539	
540	    if let Some(ref gov) = decision.governed_by {
541	        out.governed_by.insert(pkg.clone(), gov.clone());
542	    }
543	
544	    let new_t = bump_target(pkg, sev, input)?;
545	    out.targets.insert(pkg.clone(), new_t);
546	    worklist.insert(pkg.clone());
547	
548	    for sib in groups.fixed_siblings(pkg) {
549	        let sib_sev = out.severities.get(sib).copied().unwrap_or(Severity::None);
550	        if sev > sib_sev {
551	            out.severities.insert(sib.clone(), sev);
552	            out.reasons.insert(
553	                sib.clone(),
554	                BumpReason::FixedGroupUnion {
555	                    group: groups
556	                        .fixed_group_of(pkg)
557	                        .expect("a fixed-group sibling implies the package has a fixed group")
558	                        .name
559	                        .clone(),
560	                },
561	            );
562	            let sib_t = bump_target(sib, sev, input)?;
563	            out.targets.insert(sib.clone(), sib_t);
564	            worklist.insert(sib.clone());
565	        }
566	    }
567	
568	    Ok(true)
569	}
