602	/// Rewrites one dependency edge toward `new`. A range a consumer's published manifest would keep excluding `new`
603	/// stops the run; only a dev dependency, which consumers never install, is left alone with a warning.
604	pub(crate) fn rewrite_edge(edge: &DepEdge, new: &Version, cfg: &CascadeConfig) -> Result<RewriteOutcome, GraphError> {
605	    let eco = manifest_ecosystem(&edge.from_manifest);
