            message: e.to_string(),
        })?;
    }

    let existing = callisto_model::strict_fs::read_optional(&full_path)
        .map_err(|e| ChangelogError::ReadFailed {
            path: changelog_path.to_path_buf(),
            message: e.to_string(),
        })?
        .unwrap_or_else(|| format!("# {display_name}\n\n"));

    // Normalise CRLF → LF so the prefix patterns always match, then restore
    // the original line endings on the way out if the file used CRLF.
    let had_crlf = existing.contains("\r\n");
    let (bom, existing) = match existing.strip_prefix('\u{feff}') {
        Some(rest) => ("\u{feff}", rest),
        None => ("", existing.as_str()),
    };
    let normalised = if had_crlf {
        existing.replace("\r\n", "\n")
    } else {
        existing.to_owned()
    };

    // A rerun must not duplicate a version heading: skip the write when it already exists. The heading is the
    // first line of `rendered` (e.g. "## 1.0.0").
    let version_heading = rendered.lines().next().unwrap_or("").trim();
    if !version_heading.is_empty() && has_heading(&normalised, version_heading) {
        return Ok(());
    }

    // Every header shape splices the new entry the same way; only the rest of the file to keep differs.
    let rest: &str = if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n\n")) {
        rest
    } else if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n")) {
        rest
    } else if let Some(rest) = strip_alias_title(&normalised, display_name) {
        rest
    } else {
        // No matching H1 found: emit the correct H1 first so the output is
        // well-formed, keeping the entire existing content as the body.
        &normalised
    };

    let mut new_content = String::from(bom);
    new_content.push_str(&format!("# {display_name}\n\n"));
    new_content.push_str(rendered);
    if !rendered.ends_with('\n') {
        new_content.push('\n');
    }
    new_content.push('\n');
    new_content.push_str(rest);

    if had_crlf {
        new_content = new_content.replace('\n', "\r\n");
    }

    callisto_model::atomic::atomic_write(&full_path, &new_content, permit).map_err(|e| ChangelogError::WriteFailed {
        path: changelog_path.to_path_buf(),
        message: e.to_string(),
    })
}

/// Whether `heading` starts a line of `text` outside a fenced code block. An indented line or a line in a code
/// example only mentions the heading.
pub(in crate::changelog) fn has_heading(text: &str, heading: &str) -> bool {
    let mut fences = Fences::default();
    text.lines()
        .any(|line| !fences.is_code(line) && line.trim_end() == heading)
}

/// The text after a leading `# title` that names this package under another display form: a bare name that later
/// gained its ecosystem prefix, or the reverse. A title for anything else is kept.
fn strip_alias_title<'a>(text: &'a str, display_name: &str) -> Option<&'a str> {
    const ECOSYSTEMS: [&str; 3] = ["cargo", "npm", "pypi"];
    let (first, rest) = text.split_once('\n')?;
    let title = first.strip_prefix("# ")?.trim_end();
    let is_alias = ECOSYSTEMS.iter().any(|ecosystem| {
        display_name.strip_prefix(&format!("{ecosystem}/")) == Some(title)
            || format!("{ecosystem}/{display_name}") == title
    });
    is_alias.then(|| rest.strip_prefix('\n').unwrap_or(rest))
}

/// The non-empty `## {version}` section body, trimmed.
pub fn extract_section<'a>(changelog: &'a str, version: &Version) -> Option<&'a str> {
    find_section(changelog, version).filter(|section| !section.is_empty())
}

/// The trimmed `## {version}` section body, empty when the heading has no content;
/// `None` only when the heading is absent.
pub fn find_section<'a>(changelog: &'a str, version: &Version) -> Option<&'a str> {
    let target_heading = format!("## {}", version.render());
    let mut start_byte = None;

    let mut offset = 0;
    for line in changelog.split_inclusive('\n') {
        let trimmed = line.trim_end();
        if trimmed == target_heading {
            start_byte = Some(offset + line.len());
            break;
        }
        offset += line.len();
    }

    let start = start_byte?;
    let slice_after = &changelog[start.min(changelog.len())..];

    let mut end = slice_after.len();
    let mut line_offset = 0;
    let mut fences = Fences::default();

    for line in slice_after.split_inclusive('\n') {
        let in_code = fences.is_code(line);
        // The sections Callisto writes start at column 0; a heading-like line in a summary is indented under its bullet.
        let heading = line.starts_with("## ") || line.starts_with("# ");
        if line_offset > 0 && !in_code && heading {
            end = line_offset;
            break;
        }
        line_offset += line.len();
    }

    Some(slice_after[..end.min(slice_after.len())].trim())
}

#[cfg(test)]
mod tests {

    /// Tests exercise the write primitives directly rather than through a
    /// command handler, so they mint a permit without a dry-run flag to
    /// consult. Every non-test caller must go through
    /// `ApplyPermit::granted_unless_dry_run`.
    fn permit() -> callisto_model::ApplyPermit {
        callisto_model::ApplyPermit::force_for_tests()
    }
    use super::*;
    use callisto_model::VersionGrammar;

    #[test]
    fn extracts_rendered_section() {
        let changelog = r#"# my-pkg

## 1.1.0

### Minor Changes

- Add cool feature

## 1.0.0

### Patch Changes

- Initial release
"#;
        let v1_1 = Version::parse("1.1.0", VersionGrammar::SemVer).unwrap();
        let extracted = extract_section(changelog, &v1_1).unwrap();
        assert!(extracted.contains("### Minor Changes"));
        assert!(extracted.contains("- Add cool feature"));
        assert!(!extracted.contains("## 1.0.0"));
    }

    #[test]
    fn extracts_crlf_changelog_section() {
        let changelog = "# my-pkg\r\n\r\n## 1.1.0\r\n\r\n### Minor Changes\r\n\r\n- Feature\r\n\r\n## 1.0.0\r\n";
        let v1_1 = Version::parse("1.1.0", VersionGrammar::SemVer).unwrap();
        let extracted = extract_section(changelog, &v1_1).unwrap();
        assert!(extracted.contains("### Minor Changes"));
        assert!(extracted.contains("- Feature"));
    }

    #[test]
    fn find_section_tells_an_empty_section_from_a_missing_heading() {
        let changelog = "# my-pkg\n\n## 1.1.0\n\n## 1.0.0\n\n- Initial\n";
        let v1_1 = Version::parse("1.1.0", VersionGrammar::SemVer).unwrap();
        let v2 = Version::parse("2.0.0", VersionGrammar::SemVer).unwrap();
